package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CollectionType_construct_TriageGen0Test {

    @Test
    public void testConstruct_WithListAndInteger() {
        // Given
        Class<?> rawType = List.class;
        JavaType elemT = TypeFactory.defaultInstance().constructType(Integer.class);

        // When
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Then
        assertNotNull("Result should not be null", result);
        assertEquals("Raw type should match", rawType, result.getRawClass());
        assertEquals("Element type should match", elemT, result.getElementType());

        // Verify internal state via toString or other available mechanisms 
        // since the constructor is protected and fields are largely private
        String toStringResult = result.toString();
        assertTrue("toString should contain raw type", toStringResult.contains("java.util.List"));
        assertTrue("toString should contain element type", toStringResult.contains("int"));
    }

    @Test
    public void testConstruct_WithSetAndString() {
        // Given
        Class<?> rawType = java.util.Set.class;
        JavaType elemT = TypeFactory.defaultInstance().constructType(String.class);

        // When
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Then
        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemT, result.getElementType());
    }

    @Test
    public void testConstruct_WithCustomClass() {
        // Given
        class MyCollection extends java.util.ArrayList<String> {}
        Class<?> rawType = MyCollection.class;
        JavaType elemT = TypeFactory.defaultInstance().constructType(String.class);

        // When
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Then
        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemT, result.getElementType());
    }

    @Test(expected = NullPointerException.class)
    public void testConstruct_WithNullRawType() {
        // Given
        Class<?> rawType = null;
        JavaType elemT = TypeFactory.defaultInstance().constructType(Integer.class);

        // When
        CollectionType.construct(rawType, elemT);

        // Then: Expect NullPointerException because the constructor or internal logic uses rawType
    }

    @Test(expected = NullPointerException.class)
    public void testConstruct_WithNullElemT() {
        // Given
        Class<?> rawType = List.class;
        JavaType elemT = null;

        // When
        CollectionType.construct(rawType, elemT);

        // Then: Expect NullPointerException
    }
}
